int main(int argc,char** argv){try{std::string adapter;if(argc==3&&std::string(argv[1])=="--adapter")adapter=argv[2];else if(argc!=1)throw std::runtime_error("Usage: native_smoke_sharing_tests [--adapter substring]");std::ifstream stream("build/smoke-sharing/fixture.cooked.json",std::ios::binary);std::string bytes{std::istreambuf_iterator<char>(stream),std::istreambuf_iterator<char>()};auto asset=e::parseCooked(bytes);Rig rig(adapter);require(rig.debug,"Actual GPU validation layer required");lifecycle(rig,asset);subscriptionAndDemotion(rig,asset);fairnessAndInvalidGrid(rig,asset);pinnedBudget(rig,asset);queueAndInputValidation(rig,asset);naturalTail(rig,asset);const auto errors=rig.debugErrors();require(errors==0,"Smoke sharing debug errors");std::cout<<Json{{"schema","nativegpu.smoke-sharing-evidence/1"},{"ok",true},{"groups",groups},{"checks",checks},{"comparisons",comparisons},{"cases",cases},{"adapter",rig.adapter},{"debugLayer",rig.debug},{"debugErrors",errors},{"runtimeReadback",false},{"scope","Automatic GPU smoke service observation/publication/pause/retirement, demand allocation, quota/fence/backpressure. No renderer WF coverage selection or full B/D/A-G acceptance."}}.dump()<<'\n';}catch(const std::exception& ex){std::cerr<<"Smoke sharing failed after "<<checks<<" checks: "<<ex.what()<<'\n';return 1;}}
